-- Date and time functions vs sqlite3 3.53.4 (#651): one statement per
-- line, run by tools/check_row_functions_oracle.py. 'localtime' is not
-- exercised (it depends on the host's zone); 'utc' only on values
-- already known to be UTC.
-- time values: dates, times, separators
SELECT date('2024-03-15'), time('2024-03-15'), datetime('2024-03-15')
SELECT datetime('2024-03-15 13:45'), datetime('2024-03-15 13:45:30'), datetime('2024-03-15 13:45:30.123')
SELECT datetime('2024-03-15T13:45:30'), datetime('2024-03-15TT13:45'), datetime('2024-03-15   13:45')
SELECT datetime('2024-03-15 13:45:30.9999'), time('2024-03-15 13:45:30.5'), datetime('2024-03-15 ')
SELECT time('13:45'), time('13:45:30'), time('13:45:30.250'), date('13:45'), datetime('13:45')
SELECT time('24:00'), datetime('24:00:00'), time('25:00'), time('12:60'), time('12:30:60')
SELECT date('2024-1-01'), date('24-01-01'), date('2024-01-1'), date('2024/01/01'), date('20240101')
SELECT date('2024-00-10'), date('2024-13-01'), date('2024-01-00'), date('2024-01-32'), date('2024-01-31')
SELECT date('2026-02-30'), date('2026-02-29'), date('2024-02-29'), date('2024-02-30'), date('2023-04-31')
SELECT datetime('2026-02-30 10:00'), julianday('2026-02-30'), date('1900-02-29'), date('2000-02-29'), date('2100-02-29')
SELECT date(''), date(' '), date('abc'), date('2024-03-15x'), date('2024-03-15 13:45x')
SELECT datetime('2024-03-15 13:45:30.'), datetime('2024-03-15 13:45:3'), datetime('2024-03-15 1:45'), time('13:4')
-- timezones
SELECT datetime('2024-03-15 13:45Z'), datetime('2024-03-15 13:45z'), datetime('2024-03-15 13:45 Z '), datetime('2024-03-15 13:45:30.5Z')
SELECT datetime('2024-03-15 13:45+02:00'), datetime('2024-03-15 13:45-05:30'), datetime('2024-03-15 13:45 +01:00')
SELECT datetime('2024-03-15 01:00+02:00'), datetime('2024-12-31 23:00-02:00'), date('2024-01-01 00:30+01:00')
SELECT datetime('2024-03-15 13:45+14:00'), datetime('2024-03-15 13:45+15:00'), datetime('2024-03-15 13:45+02:60'), datetime('2024-03-15 13:45+2:00')
SELECT time('13:45+02:00'), time('13:45:10-01:15'), datetime('13:45+02:00'), datetime('2024-03-15+02:00'), datetime('2024-03-15Z')
SELECT datetime('2024-03-15 13:45+00:00'), datetime('2024-03-15 13:45+02:00x'), datetime('2024-03-15 13:45 +02:00 ')
-- negative years and the range limits
SELECT date('-0044-03-15'), datetime('-4713-11-24 12:00:00'), datetime('-4713-11-24 11:59:59'), date('-4714-01-01')
SELECT date('0000-01-01'), date('0001-01-01'), julianday('0000-01-01'), julianday('-0001-12-31'), date('-0001-02-29')
SELECT datetime('9999-12-31 23:59:59'), datetime('9999-12-31 23:59:59.999'), julianday('9999-12-31 23:59:59.999'), datetime('10000-01-01')
SELECT strftime('%Y %F', '-0044-03-15'), strftime('%Y|%G|%g|%j|%V', '-0001-06-01'), datetime('-1000-02-29')
-- numbers: julian days, unix time, auto
SELECT date(2460385.5), datetime(2460385), datetime(2460385.25), julianday(2460385.25), datetime(0), datetime(0.0)
SELECT datetime(-1), datetime(5373484.4999999), datetime(5373484.5), datetime('2460385.5'), datetime(' 2460385.5 ')
SELECT datetime('2460385'), datetime('+2460385'), datetime('2.46e6'), datetime('1e'), datetime('.5'), datetime('5.')
SELECT datetime(1700000000, 'unixepoch'), datetime(1700000000.5, 'unixepoch'), datetime(-1, 'unixepoch'), datetime('1700000000', 'unixepoch')
SELECT datetime(1700000000123, 'unixepoch'), datetime(253402300799, 'unixepoch'), datetime(253402300800, 'unixepoch'), datetime(-210866760000, 'unixepoch')
SELECT datetime(-210866760001, 'unixepoch'), datetime(2460385.5, 'unixepoch'), datetime('2024-01-01', 'unixepoch'), datetime(0, 'unixepoch')
SELECT datetime(1700000000, 'auto'), datetime(2460385.5, 'auto'), datetime(-1, 'auto'), datetime('2024-01-01', 'auto'), datetime(1e13, 'auto')
SELECT datetime(253402300799, 'auto'), datetime(253402300800, 'auto'), datetime(-210866760000, 'auto'), datetime(5373484.5, 'auto')
SELECT datetime(2460385.5, 'julianday'), datetime(1700000000, 'julianday'), datetime('2024-01-01', 'julianday'), datetime(10, '+1 day', 'julianday')
SELECT datetime(1700000000, '+1 day', 'unixepoch'), datetime(1700000000, '+1 day', 'auto'), datetime(1700000000, 'unixepoch', 'unixepoch')
SELECT datetime(1700000000), date(1e10), julianday(1700000000), unixepoch(1700000000), unixepoch(1700000000, 'unixepoch')
SELECT datetime(1700000000, 'start of day'), datetime(1700000000, 'subsec'), datetime(1700000000, 'unixepoch', 'subsec')
-- NULLs, blobs, numeric modifiers and types
SELECT date(NULL), time(NULL), datetime(NULL), julianday(NULL), unixepoch(NULL), strftime(NULL, '2024-01-01'), strftime('%Y', NULL)
SELECT date('2024-01-01', NULL), datetime('2024-01-01', '+1 day', NULL), timediff(NULL, '2024-01-01'), timediff('2024-01-01', NULL)
SELECT date(x'323032342d30332d3135'), date('2024-01-01', x'2b3120646179'), date(x''), datetime(x'00')
SELECT date('2024-01-01', 5), date('2024-01-01', 1.5), date('2024-01-01', ''), date('2024-01-01', ' +1 day'), date('2024-01-01', '+1 day ')
SELECT typeof(date('2024-01-01')), typeof(time('2024-01-01')), typeof(datetime('2024-01-01')), typeof(julianday('2024-01-01')), typeof(unixepoch('2024-01-01'))
SELECT typeof(unixepoch('2024-01-01', 'subsec')), typeof(strftime('%s', '2024-01-01')), typeof(timediff('2024-01-02', '2024-01-01')), typeof(julianday(2460385))
SELECT julianday('2024-03-15'), julianday('2024-03-15 13:45:30.123'), julianday('2000-01-01 12:00'), julianday('13:45'), julianday(0)
SELECT unixepoch('2024-03-15'), unixepoch('1970-01-01'), unixepoch('1969-12-31 23:59:59'), unixepoch('1969-12-31 23:59:59.5'), unixepoch('-4713-11-24 12:00')
SELECT unixepoch('2024-03-15 13:45:30.123', 'subsec'), unixepoch('1969-12-31 23:59:59.5', 'subsec'), unixepoch('9999-12-31 23:59:59.999', 'subsecond')
-- NNN unit modifiers
SELECT datetime('2024-03-15 13:45', '+1 day'), datetime('2024-03-15 13:45', '-1 days'), datetime('2024-03-15 13:45', '1 day'), datetime('2024-03-15 13:45', '+1.5 days')
SELECT datetime('2024-03-15 13:45', '+3 hours'), datetime('2024-03-15 13:45', '-90 minutes'), datetime('2024-03-15 13:45', '+30 seconds'), datetime('2024-03-15 13:45', '+0.5 seconds')
SELECT datetime('2024-03-15 13:45', '+1 HOUR'), datetime('2024-03-15 13:45', '+1 Hours'), datetime('2024-03-15 13:45', '+1   hour'), datetime('2024-03-15 13:45', '+1hour')
SELECT datetime('2024-03-15 13:45', '+1 hourss'), datetime('2024-03-15 13:45', '+1 hr'), datetime('2024-03-15 13:45', '+1 fortnight'), datetime('2024-03-15 13:45', '+1')
SELECT datetime('2024-03-15', '+1 month'), datetime('2024-01-31', '+1 month'), datetime('2024-01-31', '-2 months'), datetime('2024-03-31', '-1 month')
SELECT datetime('2024-03-15', '+13 months'), datetime('2024-03-15', '-15 months'), datetime('2024-03-15', '+1.5 months'), datetime('2024-03-15', '-0.5 month')
SELECT datetime('2024-02-29', '+1 year'), datetime('2024-02-29', '-4 years'), datetime('2024-03-15', '+1.25 years'), datetime('2024-03-15', '-2024 years')
SELECT datetime('2024-03-15', '+7975 years'), datetime('2024-03-15', '+7976 years'), datetime('2024-03-15', '+14713 years'), datetime('2024-03-15', '-6737 years')
SELECT datetime('2024-03-15', '+5373485 days'), datetime('2024-03-15', '-2460385 days'), datetime('2024-03-15', '+1e3 days'), datetime('2024-03-15', '+1e-1 days')
SELECT datetime('2024-03-15', '+464270000000000 seconds'), datetime('2024-03-15', '-1000000000 seconds'), datetime('2024-03-15', '+176545 months')
SELECT datetime('2024-03-15 10:00:00', '+0.0005 seconds', 'subsec'), datetime('2024-03-15 10:00:00', '-0.0005 seconds', 'subsec'), datetime('2024-03-15', '+.5 day')
SELECT datetime('2024-03-15', '++1 day'), datetime('2024-03-15', '+-1 day'), datetime('2024-03-15', '+1e day'), datetime('2024-03-15', '1.2.3 days')
-- YMD and HMS shift modifiers
SELECT datetime('2024-03-15 13:45', '+0001-02-03'), datetime('2024-03-15 13:45', '-0001-02-03'), datetime('2024-03-31', '+0000-01-00'), datetime('2024-03-31', '-0000-01-00')
SELECT datetime('2024-03-15 13:45', '+0001-02-03 04:05'), datetime('2024-03-15 13:45', '-0001-02-03 04:05:06.5'), datetime('2024-03-15', '+0000-00-00 25:00')
SELECT datetime('2024-03-15', '+0000-12-00'), datetime('2024-03-15', '+0000-00-31'), datetime('2024-03-15', '+0000-11-30'), datetime('2024-03-15', '0001-00-00')
SELECT datetime('2024-03-15', '+10000-00-00'), datetime('2024-03-15', '-10000-00-00'), datetime('2024-03-15', '-02024-00-00'), datetime('2024-03-15', '+0001-00-00x')
SELECT datetime('2024-03-15', '+0001-00-00 12'), datetime('2024-03-15', '+0001-00-00T12:00'), datetime('2024-03-15', '+001-00-00')
SELECT datetime('2024-03-15 13:45', '+01:30'), datetime('2024-03-15 13:45', '-01:30'), datetime('2024-03-15 13:45', '01:30'), datetime('2024-03-15 13:45', '+12:00:30.5')
SELECT datetime('2024-03-15 13:45', '+24:00'), datetime('2024-03-15 13:45', '+25:00'), datetime('2024-03-15 13:45', '+1:30'), datetime('2024-03-15 13:45', '+01:30+01:00')
SELECT datetime('2024-03-15 13:45', '-00:00:00.001', 'subsec'), time('13:45', '+00:20'), time('23:45', '+00:20'), datetime('2024-03-15', '+01:30Z')
-- start of, weekday, ceiling/floor, subsec
SELECT datetime('2024-03-15 13:45:30', 'start of day'), datetime('2024-03-15 13:45:30', 'start of month'), datetime('2024-03-15 13:45:30', 'start of year')
SELECT datetime('2024-03-15 13:45', 'START OF DAY'), datetime('2024-03-15', 'start of week'), datetime('2024-03-15', 'start of  day'), datetime('2024-03-15', 'start of')
SELECT datetime('2024-03-15 13:45', 'start of month', '+1 month', '-1 day'), date('2024-03-15', 'start of year', '+59 days'), date('13:45', 'start of month')
SELECT date('2024-03-15', 'weekday 0'), date('2024-03-15', 'weekday 5'), date('2024-03-15', 'weekday 6'), date('2024-03-17', 'weekday 0'), datetime('2024-03-15 13:45', 'weekday 1')
SELECT date('2024-03-15', 'weekday 7'), date('2024-03-15', 'weekday -1'), date('2024-03-15', 'weekday 1.5'), date('2024-03-15', 'weekday 2.0'), date('2024-03-15', 'WEEKDAY 3'), date('2024-03-15', 'weekday')
SELECT date('2024-03-15', 'weekday  3'), date('2024-03-15', 'weekday 3 '), date('2024-03-15', 'weekday x'), date('2024-03-15 23:00-05:00', 'weekday 6')
SELECT date('2024-01-31', '+1 month', 'floor'), date('2024-01-31', '+1 month', 'ceiling'), date('2023-01-31', '+1 month', 'floor'), date('2024-03-31', '-1 month', 'floor')
SELECT date('2024-01-30', '+1 month', 'floor'), date('2024-05-31', '+1 month', 'floor'), date('2024-02-29', '+1 year', 'floor'), date('2024-01-31', '+0001-01-00', 'floor')
SELECT date('2024-02-30', 'floor'), date('2024-02-31', 'ceiling'), date('2023-02-31', 'floor'), date('2023-02-31', '+0 days', 'floor'), date('2024-01-31', '+1 month', '+1 day', 'floor')
SELECT date('2024-01-31', '+1 month', 'start of day', 'floor'), date('2024-01-31', 'floor'), datetime('2024-01-31 10:00', '+1 month', 'floor')
SELECT datetime('2024-03-15 13:45:30.123', 'subsec'), datetime('2024-03-15 13:45:30.123', 'subsecond'), time('13:45:30.9996', 'subsec'), datetime('2024-03-15 13:45:30.123', 'SUBSEC')
SELECT datetime('2024-03-15 13:45:59.9999', 'subsec'), datetime('2024-03-15 13:45:59.9999'), time('13:45:59.9995', 'subsec'), datetime('2024-03-15', 'subsec', '+1 day')
-- utc on values already UTC, and modifier ordering rules
SELECT datetime('2024-03-15 13:45Z', 'utc'), datetime('2024-03-15 13:45+02:00', 'utc'), datetime('2024-03-15 13:45:30.5Z', 'utc', 'subsec'), datetime('2024-03-15 13:45Z', 'UTC')
