SELECT datetime('2024-03-15', 'bogus'), datetime('2024-03-15', 'auto2'), datetime('2024-03-15', 'ceil'), datetime('2024-03-15', 'florr'), datetime('2024-03-15', 'unix'), datetime('2024-03-15', 'z')
-- zero arguments and 'now' (shape only)
SELECT length(date()), length(time()), length(datetime()), typeof(julianday()), typeof(unixepoch()) -- nondeterministic
SELECT length(date('now')), length(datetime('NOW')), typeof(julianday('now')), typeof(unixepoch('now', 'subsec')), length(datetime('now', 'subsec')) -- nondeterministic
SELECT length(datetime('subsec')), length(time('subsecond')), typeof(strftime('%s')), length(strftime('%Y-%m-%d')), datetime('now') > '2026-01-01' -- nondeterministic
SELECT date('now', 'start of year') <= date('now'), datetime('now', 'utc') = datetime('now'), typeof(date('now', '+1 day')), date(' now') -- nondeterministic
-- strftime: every conversion
SELECT strftime('%d|%e|%f|%F|%G|%g|%H|%I|%j|%J|%k|%l|%m|%M|%p|%P|%R|%s|%S|%T|%u|%U|%V|%w|%W|%Y|%%', '2024-03-05 07:08:09.123')
SELECT strftime('%d|%e|%f|%F|%G|%g|%H|%I|%j|%J|%k|%l|%m|%M|%p|%P|%R|%s|%S|%T|%u|%U|%V|%w|%W|%Y|%%', '2023-12-31 23:59:59.999')
SELECT strftime('%I %l %p %P', '2024-01-01 00:30'), strftime('%I %l %p %P', '2024-01-01 12:30'), strftime('%I %l %p %P', '2024-01-01 13:30'), strftime('%I %l %p %P', '2024-01-01 11:59')
