SELECT strftime('%G-W%V-%u', '2021-01-01'), strftime('%G-W%V-%u', '2021-01-04'), strftime('%G-W%V-%u', '2020-12-31'), strftime('%G-W%V-%u', '2026-12-31'), strftime('%G-W%V-%u', '2027-01-01')
