SELECT strftime('%U %W %w', '2024-01-01'), strftime('%U %W %w', '2023-01-01'), strftime('%U %W %w', '2023-12-31'), strftime('%U %W %w', '2022-01-01'), strftime('%U %W', '2024-12-31')
SELECT strftime('%s', '2024-03-15 13:45:30.999'), strftime('%s', '1960-01-01'), strftime('%s', '2024-03-15 13:45:30.999', 'subsec'), strftime('%s', '1969-12-31 23:59:59.25', 'subsec')
SELECT strftime('%f', '2024-01-01 00:00:59.9999'), strftime('%f', '2024-01-01 00:00:00.0625'), strftime('%f', '2024-01-01 00:00:00.0005'), strftime('%f', '2024-01-01 00:00:05')
SELECT strftime('%J', '2024-03-15 13:45:30.123'), strftime('%J', '2000-01-01'), strftime('%J', '-4713-11-24 12:00'), strftime('%J', '9999-12-31 23:59:59.999'), strftime('%J', 2460385.123456789)
SELECT strftime('%Y-%m-%d', '0012-01-01'), strftime('%F', '0012-01-01'), strftime('%Y', '-0012-01-01'), strftime('%F %T', '-4713-11-24 12:00')
SELECT strftime('%G-W%V', '-4713-11-24 12:00'), strftime('%G-W%V-%u', '9999-12-31'), strftime('%U %W %j', '-4713-11-24 12:00')
