SELECT strftime('%Y'), strftime(), typeof(strftime('%Y')), strftime(2024, '2024-01-01'), strftime('%Y', '2024-01-01', '+1 year', 'start of year') -- nondeterministic
SELECT strftime('%Y', 2460385.5), strftime('%Y-%m-%d', 1700000000, 'unixepoch'), strftime('%T', '13:45'), strftime('%F', '13:45'), strftime('é%Yü', '2024-01-01')
SELECT strftime('%d', '2026-02-30'), strftime('%F', '2026-02-30', '+0 days'), strftime('%F', '2024-02-30'), strftime('%m/%d', '2024-02-31 10:00')
