-- sweep: every conversion across random dates, including BC years
SELECT strftime('%d|%e|%f|%F|%G|%g|%H|%I|%j|%J|%k|%l|%m|%M|%p|%P|%R|%s|%S|%T|%u|%U|%V|%w|%W|%Y', '-4355-02-23 06:02:15.933'), datetime('-4355-02-23 06:02:15.933', 'subsec'), julianday('-4355-02-23 06:02:15.933'), unixepoch('-4355-02-23 06:02:15.933')
